// src/cards.js
var ORIGIN = "https://cardblueprints.com";
function seoResponseHeaders(ctype) {
  return {
    "content-type": ctype,
    "cache-control": "public, max-age=3600, s-maxage=86400",
    "x-frame-options": "DENY",
    "x-content-type-options": "nosniff",
    "referrer-policy": "strict-origin-when-cross-origin",
    "permissions-policy": "camera=(), microphone=(), geolocation=(), payment=()",
    "strict-transport-security": "max-age=31536000; includeSubDomains; preload"
  };
}
__name(seoResponseHeaders, "seoResponseHeaders");
var MONTHS = [
  "january",
  "february",
  "march",
  "april",
  "may",
  "june",
  "july",
  "august",
  "september",
  "october",
  "november",
  "december"
];
var MONTH_CAP = MONTHS.map((m) => m[0].toUpperCase() + m.slice(1));
var DAYS_IN_MONTH = [31, 29, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
var RANK_WORDS = {
  A: "Ace",
  2: "Two",
  3: "Three",
  4: "Four",
  5: "Five",
  6: "Six",
  7: "Seven",
  8: "Eight",
  9: "Nine",
  10: "Ten",
  J: "Jack",
  Q: "Queen",
  K: "King"
};
var RANK_SLUG = { A: "ace", J: "jack", Q: "queen", K: "king" };
var SUIT_NAMES = { "\u2665": "Hearts", "\u2663": "Clubs", "\u2666": "Diamonds", "\u2660": "Spades" };
var SUIT_RED = { "\u2665": true, "\u2666": true, "\u2663": false, "\u2660": false };
var SUIT_DOM = {
  "\u2665": ["Emotions & Relationships", "Does this feel right? Do I trust this?"],
  "\u2663": ["Mind & Communication", "Is this smart? Can I learn from this?"],
  "\u2666": ["Values & Resources", "Is this valuable? Does it serve my goals?"],
  "\u2660": ["Work & Transformation", "What needs to change? What is the vision?"]
};
var RANK_LINES = {
  A: "the initiator of the deck \u2014 independence, drive, and fresh starts",
  2: "the connector of the deck \u2014 partnership, balance, and one-to-one bonds",
  3: "the creator of the deck \u2014 expression, growth, and communication",
  4: "the builder of the deck \u2014 structure, security, and steady value",
  5: "the explorer of the deck \u2014 change, freedom, and movement",
  6: "the keeper of the deck \u2014 responsibility, harmony, and karma",
  7: "the seeker of the deck \u2014 refinement, analysis, and deeper truth",
  8: "the powerhouse of the deck \u2014 mastery, abundance, and focused force",
  9: "the finisher of the deck \u2014 completion, release, and letting go",
  10: "the achiever of the deck \u2014 success, fulfillment, and results",
  J: "the messenger of the deck \u2014 learning, skill, and youthful fire",
  Q: "the steward of the deck \u2014 intuition, nurturing, and service",
  K: "the sovereign of the deck \u2014 authority, mastery, and leadership"
};
var PLANET_BLURBS = {
  Mercury: "how you think and communicate",
  Venus: "how you love and what you value",
  Mars: "how you act and handle conflict",
  Jupiter: "where you expand and find luck",
  Saturn: "where you are tested and grow",
  Uranus: "where breakthroughs arrive",
  Neptune: "where you dream \u2014 and can fool yourself"
};
function rankOf(c) {
  return c.slice(0, -1);
}
__name(rankOf, "rankOf");
function suitOf(c) {
  return c.slice(-1);
}
__name(suitOf, "suitOf");
function cardName(c) {
  return c === "Joker" ? "the Joker" : `${RANK_WORDS[rankOf(c)]} of ${SUIT_NAMES[suitOf(c)]}`;
}
__name(cardName, "cardName");
function cardNameNum(c) {
  return c === "Joker" ? "the Joker" : `${/^[AJQK]$/.test(rankOf(c)) ? RANK_WORDS[rankOf(c)] : rankOf(c)} of ${SUIT_NAMES[suitOf(c)]}`;
}
__name(cardNameNum, "cardNameNum");
function cardSlug(c) {
  if (c === "Joker") return null;
  const r = rankOf(c);
  return `${RANK_SLUG[r] || r}-of-${SUIT_NAMES[suitOf(c)].toLowerCase()}`;
}
__name(cardSlug, "cardSlug");
function cardLink(c) {
  const slug = cardSlug(c);
  const label = cardName(c);
  return slug ? `<a href="/birth-card/${slug}">${label}</a>` : label;
}
__name(cardLink, "cardLink");
function videoFor(card) {
  const v = videos_default[card];
  if (!v) return null;
  return {
    html: `<h2>Watch: the shadow of the ${cardName(card).replace("the ", "")}</h2>
<div class="vid"><iframe src="https://www.youtube-nocookie.com/embed/${v.id}" title="${v.title}" loading="lazy" allow="accelerometer; encrypted-media; picture-in-picture" allowfullscreen></iframe></div>
<p class="muted" style="font-size:.85rem">${v.title} \u2014 a deterministic shadow reading of this card.</p>`,
    jsonld: {
      "@context": "https://schema.org",
      "@type": "VideoObject",
      name: v.title,
      description: `A deterministic cardology shadow reading for the ${cardName(card).replace("the ", "")}.`,
      thumbnailUrl: `https://i.ytimg.com/vi/${v.id}/hqdefault.jpg`,
      uploadDate: v.date,
      embedUrl: `https://www.youtube-nocookie.com/embed/${v.id}`
    }
  };
}
__name(videoFor, "videoFor");
function suitSpan(c) {
  if (c === "Joker") return `<span class="g">\u2605</span>`;
  return `<span class="${SUIT_RED[suitOf(c)] ? "rs" : "bs"}">${suitOf(c)}</span>`;
}
__name(suitSpan, "suitSpan");
function birthCardFor(m, d) {
  let sv = 55 - (2 * m + d);
  if (sv < 0) sv += 52;
  if (sv === 0) return "Joker";
  return blueprint_default.SOLAR_TO_CARD[String(sv)];
}
