var CHART_IMAGE = { src: "/og/cardology-birthday-chart.png", width: 1600, height: 2100, alt: "Cardology birthday chart: playing card for every birthday" };
function renderBirthdayChart() {
  let head = `<th scope="col" class="daycol">Day</th>`;
  for (let m = 1; m <= 12; m++) head += `<th scope="col"><abbr title="${MONTH_CAP[m - 1]}">${MONTH_CAP[m - 1].slice(0, 3)}</abbr></th>`;
  let rows = "";
  for (let d = 1; d <= 31; d++) {
    let cells = "";
    for (let m = 1; m <= 12; m++) {
      if (d > DAYS_IN_MONTH[m - 1]) {
        cells += `<td class="none" aria-label="${MONTH_CAP[m - 1]} ${d} does not exist">\xB7</td>`;
        continue;
      }
      const c = birthCardFor(m, d);
      const isJoker = c === "Joker";
      const cls = isJoker ? "jk" : SUIT_RED[suitOf(c)] ? "rs" : "bs";
      const face = isJoker ? "Joker" : `${rankOf(c)}${suitOf(c)}`;
      cells += `<td><a class="${cls}" href="/born-on/${daySlug(m, d)}" title="${dayLabel(m, d)}: ${isJoker ? "the Joker" : cardName(c)}">${face}</a></td>`;
    }
    rows += `<tr><th scope="row">${d}</th>${cells}</tr>`;
  }
  return `<div class="chartwrap" tabindex="0" role="region" aria-label="Cardology birthday chart, months across and days down">
<table class="chart"><caption>Cardology birthday chart. Rows are days of the month, columns are months. Each cell is the playing card for that birthday and links to its page.</caption>
<thead><tr>${head}</tr></thead><tbody>${rows}</tbody></table></div>
<p class="muted" style="font-size:.86rem">Red is Hearts and Diamonds, black is Clubs and Spades. Every cell links to that birthday\u2019s page. December 31 is the Joker \u2014 the one date the 52-card map leaves unassigned.</p>
<figure class="chartfig">
<a href="${CHART_IMAGE.src}" title="Open the printable Cardology birthday chart (PNG)"><img src="${CHART_IMAGE.src}" width="${CHART_IMAGE.width}" height="${CHART_IMAGE.height}" loading="lazy" decoding="async" alt="${CHART_IMAGE.alt}"></a>
<figcaption>Printable version of the same chart. <a href="${CHART_IMAGE.src}" download="cardology-birthday-chart.png">Download the PNG</a> or pin it. Generated from the same calculation as the table above.</figcaption>
</figure>`;
}
