function renderDayIndex() {
  const title = "Cardology Birthday Chart: All 366 Birthdays";
  const desc = "Free playing-cards birthday chart \u2014 every date maps to one card in a 52-card deck. Browse all 366 birthdays, or use the calculator for an instant lookup.";
  let body = `<div class="kicker">The Solar Calendar</div><h1>Every birthday. One card.</h1>
  <p>Cardology reads a standard deck as a symbolic solar calendar \u2014 52 cards, 52 weeks, four suits, four seasons. Pick a birthday to see its card, ruling card, karma cards, and life path.</p>
  <p>Looking for a <strong>playing cards birthday chart</strong>? This directory is that chart: pick any month and day to see the birthday playing card, ruling card, and related layers. Prefer typing a date? Use the <a href="/birth-card-calculator">free birth card calculator</a> \u2014 same fixed calendar, instant result.</p>
  <h2>How to use this chart</h2>
  <ul>
  <li>Find the month across the top and the day down the side \u2014 each cell is that birthday\u2019s card, and opens its page.</li>
  <li>Or jump to the <a href="/birth-card-calculator">playing card birth card calculator</a> if you already know the date.</li>
  <li>Then read the full meaning on the matching <a href="/birth-card">birth card</a> page.</li>
  </ul>
  <h2>The birthday chart: all 366 dates</h2>` + renderBirthdayChart();
  body += CTA_BLOCK;
  const crumbs = {
    "@context": "https://schema.org",
    "@type": "BreadcrumbList",
    itemListElement: [
      { "@type": "ListItem", position: 1, name: "Home", item: `${ORIGIN}/` },
      { "@type": "ListItem", position: 2, name: "Birthday Lookup", item: `${ORIGIN}/born-on/` }
    ]
  };
  const collection = {
    "@context": "https://schema.org",
    "@type": "CollectionPage",
    name: title,
    description: desc,
    url: `${ORIGIN}/born-on/`,
    isPartOf: { "@type": "WebSite", name: "Card Blueprints", url: `${ORIGIN}/` },
    about: { "@type": "Thing", name: "Cardology birth cards by birthday" }
  };
  return shell({ title, desc, canonical: `${ORIGIN}/born-on/`, body, jsonld: [collection, crumbs] });
}
