function renderSitemap() {
  let urls = [`${ORIGIN}/born-on/`];
  for (let m = 1; m <= 12; m++)
    for (let d = 1; d <= DAYS_IN_MONTH[m - 1]; d++)
      urls.push(`${ORIGIN}/born-on/${daySlug(m, d)}`);
  return `<?xml version="1.0" encoding="UTF-8"?>
<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">
${urls.map((u) => `<url><loc>${u}</loc><changefreq>monthly</changefreq></url>`).join("\n")}
</urlset>`;
}
__name(renderSitemap, "renderSitemap");
async function handleSeo(request, url) {
  const path = url.pathname.replace(/\/+$/, "") || "/";
  let out = null, ctype = "text/html; charset=utf-8";
  if (path === "/born-on") {
    out = renderDayIndex();
  } else if (path.startsWith("/born-on/")) {
    const m0 = path.slice("/born-on/".length).match(/^([a-z]+)-(\d{1,2})$/);
    if (m0) {
      const mi = MONTHS.indexOf(m0[1]);
      const d = parseInt(m0[2], 10);
      if (mi >= 0 && d >= 1 && d <= DAYS_IN_MONTH[mi]) out = renderDayPage(mi + 1, d);
    }
    if (!out) {
      return new Response(
        shell({
          title: "Birthday not found | Card Blueprints",
          desc: "Look up any birthday's cardology birth card.",
          canonical: `${ORIGIN}/born-on/`,
          body: `<h1>That date isn't in the calendar</h1><p>Try the <a href="/born-on/">birthday index</a> \u2014 all 366 dates are there.</p>`
        }),
        { status: 404, headers: { "content-type": ctype } }
      );
    }
  } else if (path === "/sitemap-cardology.xml") {
    out = renderSitemap();
    ctype = "application/xml";
  }
  if (out === null) return null;
  return new Response(out, {
    headers: seoResponseHeaders(ctype)
  });
}
__name(handleSeo, "handleSeo");


